 ap=argparse.ArgumentParser();ap.add_argument('--results',required=True,type=Path);ap.add_argument('--out',required=True,type=Path);ap.add_argument('--audit',type=Path);a=ap.parse_args();p=a.results/'replay';cold=json.loads((p/'cold.json').read_bytes());warm=json.loads((p/'warm.json').read_bytes());cost=json.loads((a.results/'costs_sheng.json').read_bytes())['rows'];sources={s['case']:s for s in json.loads((ROOT/'results/pose_inversion_20261003/replay/sources.json').read_bytes())};audit=json.loads((a.audit or a.results/'audit_sheng.json').read_bytes());tight=audit['same_partition_tightness'];out=dict(rows=[],groups=[],truth_current_observations=audit['truth_current_observations'])
 assert len(cold)==36 and len(warm)==108 and len(tight)==108
 for w in warm:
  c=next(c for c in cold if c['proof']==w['proof']);bootstrap=math.ceil((c['total_s']+c['reference_encode_s'])*1e6+max(r['encode_ns']+r['decode_ns'] for r in cost if r['reference']==c['reference'])/1000+c['reference_install_bytes']*.4+40000);gap=math.floor((w['source_timestamp']-sources[w['old_case']]['source_timestamp'])*1e6);wait=max(0,bootstrap-gap);inc=max(t['encode_s']+t['incremental_s'] for t in w['timings'])*1e6;full=max(t['encode_s']+t['full_recheck_s'] for t in w['timings'])*1e6;base=240000+wait+w['wire_bytes']*.4+w['packet_encode_s']*1e6;row={k:w[k] for k in ('blueprint','query_index','radius_um','sigma','wire_bytes','exceptions','input_rays','lower_us','upper_us','revoked')};row.update(bootstrap_us=bootstrap,source_gap_us=gap,initialization_wait_us=wait,incremental_worst_us=inc,full_recheck_worst_us=full,packet_create_worst_us=w['packet_encode_s']*1e6,incremental_median_us=statistics.median(t['incremental_s'] for t in w['timings'])*1e6,full_recheck_median_us=statistics.median(t['full_recheck_s'] for t in w['timings'])*1e6,incremental_remaining_us=max(0,w['lower_us']-math.ceil(base+inc)),full_remaining_us=max(0,w['lower_us']-math.ceil(base+full)));tr=next(t for t in tight if all(t[k]==w[k] for k in ('blueprint','query_index','radius_um','sigma')));row.update({k:tr[k] for k in ('same_partition_raw_lower_us','representation_loss_us')});out['rows'].append(row)
 for eps in (0,5000,50000):
  for sigma in (0.,.001,.01):
   rr=[r for r in out['rows'] if r['radius_um']==eps and r['sigma']==sigma];assert len(rr)==12;out['groups'].append(dict(radius_um=eps,sigma=sigma,n=len(rr),median_wire_bytes=statistics.median(r['wire_bytes'] for r in rr),median_exceptions=statistics.median(r['exceptions'] for r in rr),median_incremental_us=statistics.median(r['incremental_median_us'] for r in rr),median_full_recheck_us=statistics.median(r['full_recheck_median_us'] for r in rr),positive_lower=sum(r['lower_us']>0 for r in rr),positive_incremental_remaining=sum(r['incremental_remaining_us']>0 for r in rr),positive_full_remaining=sum(r['full_remaining_us']>0 for r in rr),max_representation_loss_us=max(r['representation_loss_us'] for r in rr),median_representation_loss_us=statistics.median(r['representation_loss_us'] for r in rr),revoked=sum(r['revoked'] for r in rr)))
 out['scope']='All 108 fixed cases. Source construction + bounded encoding + decoding/verification +20Mbps serialization +20ms propagation +20ms clock +200ms action reserve; cold transport/proof setup and backlog paid. Worst of3 timings and5 coding repeats, not WCET. Each query/radius is a separate task, no free oracle selection. Synthetic perturbations share per-class random draws; not independent risk trials. Actual sensor/callback latency and physical links unmeasured. Same-partition loss is restricted to the inherited rule that rechecks only old excluded leaves. Old unresolved leaves remain possible; cold representation loss, all-leaf refinement and total optimality gap are not measured.';out['source_sha256']=hashlib.sha256(Path(__file__).read_bytes()).hexdigest();a.out.write_text(json.dumps(out,indent=2)+'\n')
